"""Omnitruncated {7,3} tiling generated by the (2,3,7) hyperbolic Coxeter reflection group, drawn in the band model."""

from pathlib import Path

import numpy as np
from PIL import Image

W, H, SS, P, Q, V = 2400, 720, 3, 7, 3, 0.993  # V: band half-height used
# mirrors of the fundamental triangle in the Poincaré disk: real axis, line through 0 at
# angle pi/P and circle |z - C| = R orthogonal to the unit circle
C = 1 / np.sqrt(1 - np.sin(np.pi / P) ** 2 / np.cos(np.pi / Q) ** 2)
R, ROT = np.sqrt(C**2 - 1), np.exp(1j * np.pi / P)
# vertices with angles pi/2 and pi/Q, and the incenter = Wythoff point for omnitruncation
ang = np.array([0, np.pi / P, np.pi / P / 2])
b = C * np.cos(ang) + R * np.sin(ang) * [0, 0, 1]
V1, V2, WY = (b - np.sqrt(b**2 - 1)) * np.exp(1j * ang)
VERTS = np.c_[[0, V1, V2]]  # centers of 14-gons, squares, hexagons
# tiling edges run from WY toward its mirror images: directions in the disk centered on WY
e = np.append(np.conj(WY) * ROT ** np.array([0, 2]), C + R**2 / np.conj(WY - C))
e = (e - WY) / (1 - np.conj(WY) * e)
EDIR = np.c_[e / np.abs(e)]


def render(v, u):  # per-pixel colours for flattened band coordinates
    z = np.tanh(np.pi * (u * V * W / H + 1j * v) / 4)  # band model -> Poincaré disk
    pix = np.pi / H / np.cos(np.pi * v / 2)  # hyperbolic size of one output pixel
    par = np.zeros(z.shape, bool)
    # fold into the fundamental triangle, tracking reflection parity
    for _ in range(30):
        th = np.mod(np.angle(z) + np.pi / P, 2 * np.pi / P) - np.pi / P
        z, par = np.abs(z) * np.exp(1j * np.abs(th)), par ^ (th < 0)
        m = np.abs(z - C) < R
        z, par = np.where(m, C + R**2 / np.conj(z - C), z), par ^ m
    # faces split the triangle along the edges where cosh d(z, V) / cosh d(V, WY) are equal
    ch = 1 + 2 * np.abs(z - VERTS) ** 2 / (1 - np.abs(z) ** 2) / (1 - abs(VERTS) ** 2)
    rho = 2 * np.arctanh(np.abs((VERTS - WY) / (1 - np.conj(WY) * VERTS)))
    face = np.argmin(ch / np.cosh(rho), 0)
    rr = np.clip(np.choose(face, np.arccosh(ch) / rho), 0, 1)  # relative distance
    # sinh of distances to edges (rays from WY: perpendicular if ahead, else to WY) and mirrors
    x = (z - WY) / (1 - np.conj(WY) * z)
    s = 2 * x * np.conj(EDIR)
    d_edge = np.where(s.real > 0, np.abs(s.imag), np.abs(s)).min(0) / (1 - abs(x) ** 2)
    mirrors = [2 * z.imag, -2 * (z / ROT).imag, np.abs(z - C) ** 2 / R - R]
    d_mirror = np.minimum.reduce(mirrors) / (1 - np.abs(z) ** 2)
    # stained glass faces glowing toward their centers between dark leading
    cols = np.array([[0.20, 0.06, 0.45], [1.0, 0.62, 0.18], [0.85, 0.16, 0.42]]).T
    lead = np.clip((d_edge - 0.018) / (0.7 * pix) + 0.5, 0, 1)
    halo = 0.45 * np.exp(-np.maximum(d_edge - 0.018, 0) / 0.05)
    # alternate cosets of the rotation subgroup are slightly darker
    col = cols[:, face] * lead * ((0.3 + 0.95 * rr**2) * np.where(par, 0.82, 1) + halo)
    glint = np.exp(-((d_mirror / (0.006 + 0.7 * pix)) ** 2)) * lead
    col += np.c_[[0.12, 0.108, 0.096]] * glint + np.c_[[0.03, 0.015, 0.05]] * (1 - lead)
    fade = np.exp(-pix / 0.12)  # tiles shrink below pixel size toward the boundary
    col = col * fade + np.c_[cols.mean(1)] * 0.35 * (1 - fade)
    col *= (1 - v**6) * (0.25 + 0.75 * np.exp(-((v / 0.75) ** 4)))
    return col


vu = np.mgrid[V : -V : H * SS * 1j, -1 : 1 : W * SS * 1j]  # rendered in 12 row blocks
col = np.concatenate([render(*b.reshape(2, -1)) for b in np.array_split(vu, 12, 1)], 1)
img = col.reshape(3, H, SS, W, SS).mean((2, 4)) * (1 - 0.3 * np.linspace(-1, 1, W) ** 2)
img = Image.fromarray(np.uint8(255 * (1 - np.exp(-1.5 * img.transpose(1, 2, 0))) + 0.5))
img.save(Path(__file__).with_name("banner.webp"), quality=85, method=6)
